use omt_proxy::update::*;
fn proposal()->UpdateProposal{UpdateProposal{kind:Kind::Core,source:"https://github.com/XTLS/Xray-core".into(),version:"v26.10.10".into(),digest:Some("a".repeat(64)),observed_digest:Some("a".repeat(64)),prerelease:false,observed_at:1000,compatibility:"unverified".into()}}
fn policy()->NetworkPolicy{NetworkPolicy{flight:Some(false),metered:Some(false),user_enabled:Some(true),now:1000}}
#[test] fn flight_unknown_and_metered_are_deferred(){let p=proposal();let mut n=policy();n.flight=Some(true);assert_eq!(plan_update(&p,&n).status,"paused");n.flight=None;assert_eq!(plan_update(&p,&n).status,"paused");n.flight=Some(false);n.metered=Some(true);assert_eq!(plan_update(&p,&n).status,"deferred");n.metered=None;assert_eq!(plan_update(&p,&n).status,"deferred");}
#[test] fn never_installs_or_enables_and_does_not_fake_signature(){let p=proposal();let mut n=policy();n.user_enabled=Some(false);let d=plan_update(&p,&n);assert_eq!(d.status,"review");assert!(!d.apply&&!d.enable_proxy&&!d.source_authenticated);assert_eq!(d.verification,"digest_only");assert_eq!(d.install_channel,"omarchy_then_arch");}
#[test] fn stale_future_prerelease_and_unknown_sources_rejected(){let mut p=proposal();let n=policy();p.observed_at=1001;assert_eq!(plan_update(&p,&n).status,"rejected");p.observed_at=1000;let mut later=policy();later.now+=86401;assert_eq!(plan_update(&p,&later).status,"rejected");p.prerelease=true;assert_eq!(plan_update(&p,&n).status,"rejected");p.prerelease=false;p.source="https://evil.example".into();assert_eq!(plan_update(&p,&n).status,"rejected");}
#[test] fn mismatch_digest_and_unreviewed_labels_rejected(){let mut p=proposal();let n=policy();p.observed_digest=Some("b".repeat(64));assert_eq!(plan_update(&p,&n).reason,"digest_mismatch");p.observed_digest=None;p.digest=Some("bad".into());assert_eq!(plan_update(&p,&n).status,"rejected");p.digest=None;p.version="v2.0.0-rc1".into();assert_eq!(plan_update(&p,&n).status,"rejected");}
#[test] fn metadata_only_stays_unverified(){let mut p=proposal();p.observed_digest=None;let d=plan_update(&p,&policy());assert_eq!(d.verification,"not_downloaded");assert!(!d.source_authenticated&&!d.apply);}
